package javiertorres.amazonconbackend22settembre.controller;
import javiertorres.amazonconbackend22settembre.dto.PreferitoDto; import javiertorres.amazonconbackend22settembre.service.PreferitoService; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/preferiti") public class PreferitoController {private final PreferitoService service; public PreferitoController(PreferitoService s){service=s;} @GetMapping public List<PreferitoDto> list(Authentication a){return service.list(a.getName());} @PostMapping("/{oggettoId}") @ResponseStatus(HttpStatus.CREATED) public PreferitoDto add(Authentication a,@PathVariable UUID oggettoId){return service.add(a.getName(),oggettoId);} @DeleteMapping("/{oggettoId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void remove(Authentication a,@PathVariable UUID oggettoId){service.remove(a.getName(),oggettoId);}}
